--
-- Name: search_similar_personas(public.vector, double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_similar_personas(query_embedding public.vector, similarity_threshold double precision DEFAULT 0.5, max_results integer DEFAULT 10) RETURNS TABLE(persona_id integer, similarity double precision, content_text text)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        pe.persona_id,
        1 - (pe.embedding <=> query_embedding) AS similarity,
        pe.content_text
    FROM personas_embeddings pe
    WHERE 1 - (pe.embedding <=> query_embedding) >= similarity_threshold
    ORDER BY pe.embedding <=> query_embedding
    LIMIT max_results;
END;
$$;


